import csv
import io
import re


def parse_csv(raw_csv: str):
    width = 8
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(io.StringIO(raw_csv, newline=""),
                        delimiter=",", quotechar='"', doublequote=True)
    records = list(reader)

    def fit_width(record):
        if len(record) > width:
            # Keep extra comma-separated text in the final error field.
            return record[:width - 1] + [",".join(record[width - 1:])]
        return record + [""] * (width - len(record))

    def looks_like_header(record):
        if len(record) != width:
            return False
        names = [cell.strip() for cell in record]
        return (
            len({name.casefold() for name in names}) == width
            and all(re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name)
                    for name in names)
        )

    first_nonblank = next(
        (i for i, record in enumerate(records)
         if len(record) > 1 or any(cell.strip() for cell in record)),
        None,
    )
    if first_nonblank is None:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i in range(first_nonblank, len(records))
         if looks_like_header(records[i])),
        first_nonblank,
    )
    return {
        "columns": fit_width(records[header_index]),
        "rows": [fit_width(record) for record in records[header_index + 1:]],
    }
